package com.spinplayer.app;
import android.media.*;import java.util.concurrent.TimeUnit;import java.nio.*;import java.io.*;
final class AudioValidator {
 static void verify(File file)throws Exception{MediaExtractor e=new MediaExtractor();try{e.setDataSource(file.getAbsolutePath());for(int i=0;i<e.getTrackCount();i++){MediaFormat f=e.getTrackFormat(i);if(f.getString(MediaFormat.KEY_MIME).startsWith("audio/")){e.selectTrack(i);decodeSample(e,f);return;}}throw new IOException("NoAudioTrack");}finally{e.release();}}
 static void decodeSample(MediaExtractor extractor,MediaFormat format)throws Exception{MediaCodec codec=null;boolean started=false;try{codec=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));codec.configure(format,null,null,0);codec.start();started=true;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();boolean eos=false;long bytes=0,deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(15);while(System.nanoTime()<deadline){if(!eos){int in=codec.dequeueInputBuffer(10000);if(in>=0){ByteBuffer buffer=codec.getInputBuffer(in);buffer.clear();int size=extractor.readSampleData(buffer,0);if(size<0){codec.queueInputBuffer(in,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);eos=true;}else{codec.queueInputBuffer(in,0,size,Math.max(0,extractor.getSampleTime()),0);extractor.advance();}}}int out=codec.dequeueOutputBuffer(info,10000);if(out>=0){bytes+=info.size;boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0||info.presentationTimeUs>=3000000;codec.releaseOutputBuffer(out,false);if(done){if(bytes<=0)throw new IOException("EmptyDecodedAudio");return;}}}throw new IOException("DecodeSampleTimeoutOrCancelled");}finally{if(codec!=null){if(started)try{codec.stop();}catch(Exception ignored){}codec.release();}}}
}
